const pending = new Set();
const profileVersion = '1';
const setting = (key, fallback) => MODS.getSetting(key, fallback);
const trim = (text, limit) => { const clean = String(text || '').replace(/\s+/g, ' ').trim(); if (clean.length <= limit) return clean; const room = Math.max(1, limit - 1); const cut = clean.slice(0, room + 1); const word = cut.lastIndexOf(' '); return `${cut.slice(0, word > 0 ? word : room).trim().replace(/[.!?]+$/, '')}.`; };
const resetRuntime = () => pending.clear();
MODS.registerNarrationOrchestrator({ id: 'template-exchange', priority: 5, isActive: async () => setting('enabled', true) });
MODS.registerHook('onSceneBeat', envelope => { if (envelope?.exchangeId) pending.add(envelope.exchangeId); });
MODS.registerHook('onSceneExchangeClosed', async envelope => {
  const targetId = envelope?.exchangeId;
  if (!targetId || !pending.delete(targetId) || !(await MODS.ownsNarrationExchange(envelope))) return;
  const context = MODS.getNarrationContext({ exchangeId: targetId, recentBeatLimit: 1, activityLimit: 0 });
  const summaries = (envelope.beats || []).map(beat => beat?.summary).filter(Boolean);
  if (!summaries.length) return;
  const includeLocation = await setting('includeLocation', true);
  const location = includeLocation ? String(context.location?.label || '').trim() : '';
  const maximum = await setting('maxCharacters', 400);
  const text = trim([location ? `${location}:` : '', summaries.join(' ')].filter(Boolean).join(' '), maximum);
  MODS.publishNarration({ id: `yaw_narration_template_first_party.v${profileVersion}.exchange.${targetId}`, scope: 'exchange', targetId, status: 'ready', text, profileId: 'deterministic-template', profileVersion, providerId: 'offline-template', outputRating: envelope.policy?.posture === 'mature' ? 'mature' : 'safe' });
});
MODS.registerHook('onContentPolicyChanged', resetRuntime);
MODS.registerHook('onGameStart', resetRuntime);
MODS.registerHook('onGameLoad', resetRuntime);
